-- IPS Project 7.2 — expand factory PRISM graphics with real data-driven scenes.

begin;

create or replace function public.ips_prism_factory_document_v2(p_key text)
returns jsonb
language plpgsql immutable
as $$
begin
case p_key

when 'vs.fullscreen' then return $json$
{"schemaVersion":1,"canvas":{"width":1920,"height":1080,"transparent":true},"name":"PRISM Match VS","designTokens":{"accent":"#19d18f"},"safeArea":{"top":54,"right":96,"bottom":54,"left":96},"elements":[
