revoke all on function public.ips_prism_factory_document_v2(text) from public,anon;
grant execute on function public.ips_prism_factory_document_v2(text) to authenticated,service_role;

with pkg as (
 select * from public.broadcast_packages where slug='ips-prism' and is_factory limit 1
),
scene_rows(scene_key,name,category,replacement_group,priority) as (
 values
 ('vs','Match VS','MATCH','fullscreen',80),
 ('batter-info','Batter Info','PLAYER','player-feature',70),
 ('bowler-info','Bowler Info','BOWLER','player-feature',70),
 ('need-from','Need X From X','SITUATION','lower-third',60),
 ('partnership','Current Partnership','SITUATION','lower-third',60),
 ('playing-xi','Playing XI','MATCH','fullscreen',80),
 ('batting-scorecard','Live Batting Scorecard','SCORECARDS','fullscreen',80),
 ('bowling-scorecard','Live Bowling Scorecard','SCORECARDS','fullscreen',80),
 ('50','Fifty','EVENT','event',90),
 ('100','Century','EVENT','event',90)
),
scenes as (
 insert into public.broadcast_scenes(package_id,scene_key,name,category,description,factory_locked,director_visible,director_label,replacement_group,default_priority)
 select pkg.id,r.scene_key,r.name,r.category,'IPS PRISM factory graphic',true,true,upper(r.name),r.replacement_group,r.priority
 from pkg cross join scene_rows r
 on conflict(package_id,scene_key) do update set name=excluded.name,category=excluded.category,factory_locked=true,director_visible=true,replacement_group=excluded.replacement_group,default_priority=excluded.default_priority
 returning id,scene_key
),
variant_rows(scene_key,variant_key,name,presentation,is_default,priority,replacement_group,conflict_behavior,duration_ms,direct_take,automation) as (
 values
 ('vs','fullscreen','PRISM Match VS','FULLSCREEN',true,80,'fullscreen','HIDE_SCOREBAR',7000,false,false),
 ('batter-info','large','PRISM Batter Info','CARD',true,70,'player-feature','COEXIST',5500,false,false),
 ('bowler-info','large','PRISM Bowler Info','CARD',true,70,'player-feature','COEXIST',5500,false,false),
 ('need-from','lower-third','PRISM Need X From X','LOWER_THIRD',true,60,'lower-third','COEXIST',4800,true,false),
 ('partnership','lower-third','PRISM Current Partnership','LOWER_THIRD',true,60,'lower-third','COEXIST',5000,true,false),
 ('playing-xi','home','PRISM Playing XI — Home','FULLSCREEN',true,80,'fullscreen','HIDE_SCOREBAR',10000,false,false),
 ('playing-xi','away','PRISM Playing XI — Away','FULLSCREEN',false,80,'fullscreen','HIDE_SCOREBAR',10000,false,false),
 ('batting-scorecard','fullscreen','PRISM Live Batting Scorecard','FULLSCREEN',true,80,'fullscreen','HIDE_SCOREBAR',10000,false,false),
 ('bowling-scorecard','fullscreen','PRISM Live Bowling Scorecard','FULLSCREEN',true,80,'fullscreen','HIDE_SCOREBAR',10000,false,false),
 ('50','fullscreen','PRISM FIFTY Fullscreen','FULLSCREEN',true,90,'event','HIDE_SCOREBAR',4200,false,true),
 ('50','lower-third','PRISM FIFTY Lower Third','LOWER_THIRD',false,90,'event','COEXIST',3500,false,true),
 ('100','fullscreen','PRISM CENTURY Fullscreen','FULLSCREEN',true,90,'event','HIDE_SCOREBAR',4800,false,true),
 ('100','lower-third','PRISM CENTURY Lower Third','LOWER_THIRD',false,90,'event','COEXIST',4000,false,true)
),
variants as (
 insert into public.broadcast_variants(scene_id,variant_key,name,presentation,is_default,priority,replacement_group,conflict_behavior,default_duration_ms,direct_take,retrigger_policy,automation_eligible)
 select s.id,v.variant_key,v.name,v.presentation,v.is_default,v.priority,v.replacement_group,v.conflict_behavior,v.duration_ms,v.direct_take,'RESTART',v.automation
 from scenes s join variant_rows v using(scene_key)
 on conflict(scene_id,variant_key) do update set name=excluded.name,presentation=excluded.presentation,is_default=excluded.is_default,priority=excluded.priority,replacement_group=excluded.replacement_group,conflict_behavior=excluded.conflict_behavior,default_duration_ms=excluded.default_duration_ms,direct_take=excluded.direct_take,automation_eligible=excluded.automation_eligible
 returning id,scene_id,variant_key
),
published as (
 insert into public.broadcast_variant_versions(variant_id,version_no,status,document,source,published_at)
 select v.id,1,'PUBLISHED',public.ips_prism_factory_document_v2(s.scene_key||'.'||v.variant_key),'FACTORY',now()
 from variants v join scenes s on s.id=v.scene_id
 on conflict(variant_id,version_no) do update set document=excluded.document,status='PUBLISHED',source='FACTORY',published_at=now()
 returning id
),
release_no as (
 select coalesce(max(r.version_no),0)+1 version_no from public.broadcast_package_releases r join pkg on pkg.id=r.package_id
)
insert into public.broadcast_package_releases(package_id,version_no,manifest,theme,checksum)
select pkg.id,release_no.version_no,public.ips_broadcast_build_release_manifest(pkg.id),pkg.theme,'ips-prism-factory-2'
from pkg cross join release_no;

commit;
